  "cjkSample": "北极星素材图鉴开源字体图标动效特效许可把今天交给一颗星中文回退测试提醒夜阑昼白暮蓝暖砂天蓝护眼绿完成删除重复项目日期设置主题工作周报整理收件箱预约牙医该交了每周一今天明天已完成年月日时分秒星期把六套主题的对比图补进给安装包一份声明中文字体子集化压住体积确认的许可冲突真字体试排台描边一致性对比可重播实验零运行时纹理与光全部素材可搜筛排序打进意味着什么落到这个仓库的真实文件结论先行保持现状组合已经成立本轮没有找到换了明显更好的理由真正该补的是合规与体积仓库目前没文件而四套字体随安装包再分发未子集化是安装包体积的最大头动效自己写就够了个配方里是的纯引入都会带来许可或体积问题且循环播放违反设计约束三个许可陷阱上游登记与声明冲突是必须署名的包标但字体本体走自定义尺寸描边粗细色调继承信号弱化提醒字号字重字样内容极光强度颗粒圆角缩放动效速度减弱恢复默认参数导出清单生成现有四套无衬线等宽全部数据来源本页所有事实字段由下的抓取脚本生成字体来自的包许可证与版本来自图标与集合许可来自官方与上游登记表抓取结果原始存放在可复现字体文件仅供本页预览不建议提交进应用运行时的正确引入方式是包风险署名自定义协议存疑保留现状建议采纳值得考虑备选建议避开许可来源推荐用途集成方式契合度建议类别名称上游许可网格描边可调是否真描边填充轮廓需换字重变体官网选型判断下载体积分片实测整包解包后含全部字重与分片可变轴非可变单字重分片数用途判断来源仓库复制安装命令看试排这一条显示条排序，。、：；？！（）「」·—…％",
